from odoo import api, models


class PurchaseOrder(models.Model):
    _inherit = 'purchase.order'

    def _prepare_picking(self):
        vals = super()._prepare_picking()
        if self.picking_type_id.propagate_sale_carrier and 'carrier_id' not in vals:
            order = self.group_id.sale_id or self._get_sale_orders()[:1]
            if order.carrier_id:
                vals['carrier_id'] = order.carrier_id.id
        return vals

    @api.model
    def _confirm_dropship_purchases(self, sale_order_ids):
        """Confirm the draft purchases generated by these sale orders, which creates their
        dropships (setup scripts and demo data)."""
        orders = self.env['sale.order'].browse(sale_order_ids)
        purchases = orders._get_purchase_orders().filtered(lambda po: po.state in ('draft', 'sent'))
        purchases.button_confirm()
        return purchases.ids
